with base as (select id, store_id, product_id, quantity, last_restock, datediff(current_date(), last_restock) as days_since_last_restock from inventory where last_restock > to_date('2023-07-07') and month(last_restock) in (9, 10, 12)) select product_id, date_trunc('month', last_restock) as activity_month, bit_and(quantity) as quantity_bit_and, bit_or(quantity) as quantity_bit_or, round(avg(days_since_last_restock), 2) as avg_days_since_last_restock, avg(days_since_last_restock) as avg_days_since_last_restock_2, max(quantity) as max_quantity, bit_and(quantity) as quantity_bit_and_2, grouping_id() as gid from base group by grouping sets ((product_id, date_trunc('month', last_restock)), (product_id), ());
